// Normalize a typed guess or an alias for matching: lowercase, strip
// diacritics, punctuation to spaces, collapse. Shared by the client and
// the verifier so the accepted-answer audit tests the real matcher.
export const normGuess = (s) => String(s || '').toLowerCase().normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();

// alias -> entity code, built once. Every entity answers to its display
// name plus its listed alternates.
export function buildAliasMap() {
  const m = new Map();
  for (const [code, e] of Object.entries(BORDERS)) {
    for (const a of [e.name, ...(e.alt || [])]) m.set(normGuess(a), code);
  }
  return m;
}

// Aliases that are a proper PREFIX of some other entity's alias can never
// auto-commit while typing (uk/ukraine, niger/nigeria, guinea/guinea-bissau,
// dominica/dominican republic): they commit on Enter only.
export function buildPrefixAmbiguous(aliasMap) {
  const keys = [...aliasMap.keys()];
  const bad = new Set();
  for (const k of keys) {
    for (const other of keys) {
      if (other !== k && other.startsWith(k) && aliasMap.get(other) !== aliasMap.get(k)) { bad.add(k); break; }
    }
  }
  return bad;
}
